style.css:
@-moz-document domain("youtube.com") {
/* Set wallpaper as background */
  body {
    background-image: url(https://i.imgur.com/NlfeLpk.png);
    background-size: cover;
    background-attachment: fixed;
    background-position: center;
    background-repeat: no-repeat;
    color: #ffffff !important;
  }

  /* Transparent background for main containers */
  #container, ytd-app, ytd-masthead, ytd-page-manager, ytd-two-column-browse-results-renderer, ytd-watch-flexy {
    background: rgba(0, 0, 0, 0.7) !important;
  }

  /* Sidebar */
  ytd-mini-guide-renderer, ytd-guide-renderer {
    background: rgba(0, 0, 0, 0.6) !important;
  }

  /* Video titles and text */
  h1, h2, h3, yt-formatted-string, span {
    color: #e0e0e0 !important;
  }

  /* Search bar */
  input#search {
    background: rgba(50, 50, 50, 0.8) !important;
    color: #ffffff !important;
  }

  /* Hide default background */
  ytd-masthead, ytd-app {
    background-color: transparent !important;
  }
}
